class ViewStore {
  constructor(db, { intervalMs = 500, threshold = 100 } = {}) {
    this.db = db;
    db.exec(`CREATE TABLE IF NOT EXISTS post_views (post_id TEXT PRIMARY KEY, views INTEGER NOT NULL DEFAULT 0)`);
    this.upsert = db.prepare(`INSERT INTO post_views(post_id, views) VALUES(?, ?) ON CONFLICT(post_id) DO UPDATE SET views = views + excluded.views`);
    // allow injection for tests
    ...
