Flush:
```js
flush() {
  if (this.flushing) return; // avoid concurrent flush
  const snapshot = new Map(this.pending);
  if (snapshot.size === 0) return;
  this.flushing = true;
  try {
    const tx = this.db.transaction(() => {
      const stmt = this.upsert;
      for (const [id, n] of snapshot) stmt.run(id, n);
    });
    tx();
    // zero memory only after commit: subtract snapshot
    for (const [id, n] of snapshot) {
      const cur = this.pending.get(id);
      if (cur === undefined) { /* shouldn't happen since we never delete */ }
      ...
    }
  } finally { this.flushing = false; }
