export class ViewStore {
  constructor({ db, intervalMs = 500, threshold = 100, upsertStatement } = {}) {
    this.db = db;
    this.intervalMs = intervalMs;
    this.threshold = threshold;
    this.pending = new Map();
    this.upsert = upsertStatement ?? db.prepare(
      `INSERT INTO post_views (post_id, views) VALUES (?, ?)
       ON CONFLICT(post_id) DO UPDATE SET views = views + excluded.views`
    );
    this.select = db.prepare(`SELECT views FROM post_views WHERE post_id = ?`);
    this.flushTimer = null;
    this.flushScheduled = false;
    this.flushing = false;
    this.lastError = null;
  }

  start() { this.flushTimer = setInterval(() => this.flush(), this.intervalMs); this.flushTimer.unref?.(); }
  stop() { clearInterval(this.flushTimer); }

  increment(id) {
    const next = (this.pending.get(id) ?? 0) + 1;
    this.pending.set(id, next);
    if (next > this.threshold && !this.flushScheduled) {
      this.flushScheduled = true;
      setImmediate(() => { this.flushScheduled = false; this.flush(); });
    }
  }

  views(id) {
    const row = this.select.get(id);
    return (row ? row.views : 0) + (this.pending.get(id) ?? 0);
  }

  flush() {
    if (this.flushing || this.pending.size === 0) return;
    const snapshot = new Map(this.pending);
    this.flushing = true;
    try {
      this.db.transaction(() => {
        for (const [id, n] of snapshot) this.upsert.run(id, n);
      })();
    } catch (err) {
      this.lastError = err;
      return err ... // rethrow? For tests we want to detect failure. Maybe emit 'error'. Return without clearing.
    } finally {
      this.flushing = false;
    }
    // commit succeeded -> zero memory
    for (const [id, n] of snapshot) {
      const remaining = (this.pending.get(id) ?? 0) - n;
      if (remaining > 0) this.pending.set(id, remaining); else this.pending.delete(id);
    }
    this.lastError = null;
  }
}
```

