import Database from 'better-sqlite3';

/**
 * Concurrent-safe, batched view counter.
 *
 * - `increment(id)` only touches in-memory deltas (single-threaded JS makes
 *   this atomic; no locking needed).
 * - A background loop flushes deltas to SQLite every `intervalMs`.
 * - Any single counter exceeding `threshold` triggers an immediate flush.
 * - All deltas for a flush round are written in ONE transaction and the
 *   in-memory counters are zeroed ONLY after the transaction commits.
 * - If the flush throws (e.g. mocked statement failure), memory is left
 *   intact so the next attempt retries the exact same deltas: no loss,
 *   no double-counting.
 */
export class ViewStore {
  constructor({
    db = new Database(':memory:'),
    intervalMs = 500,
    threshold = 100,
    upsertStatement,
  } = {}) {
    this.db = db;
    this.intervalMs = intervalMs;
    this.threshold = threshold;

    db.exec(`
      CREATE TABLE IF NOT EXISTS post_views (
        post_id TEXT PRIMARY KEY,
        views   INTEGER NOT NULL DEFAULT 0
      )
    `);

    // Injectable for tests (mock a failing statement).
    this.upsert =
      upsertStatement ??
      db.prepare(`
        INSERT INTO post_views (post_id, views) VALUES (?, ?)
        ON CONFLICT(post_id) DO UPDATE SET views = views + excluded.views
      `);
    this.select = db.prepare(
      'SELECT views FROM post_views WHERE post_id = ?'
    );

    /** @type {Map<string, number>} unflushed deltas */
    this.pending = new Map();
    this.flushTimer = null;
    this.flushScheduled = false;
    this.flushing = false;
    this.lastError = null;
    this.flushCount = 0;
  }

  start() {
    if (this.flushTimer) return;
    this.flushTimer = setInterval(() => this.flush(), this.intervalMs);
    this.flushTimer.unref?.();
  }

  stop() {
    clearInterval(this.flushTimer);
    this.flushTimer = null;
  }

  /** O(1), synchronous, safe under concurrency (Node runs handlers serially). */
  increment(postId) {
    const next = (this.pending.get(postId) ?? 0) + 1;
    this.pending.set(postId, next);
    if (next > this.threshold && !this.flushScheduled) {
      this.flushScheduled = true;
      setImmediate(() => {
        this.flushScheduled = false;
        this.flush();
      });
    }
  }

  /** Exact read: committed DB value + unflushed in-memory delta. */
  views(postId) {
    const row = this.select.get(postId);
    return (row ? row.views : 0) + (this.pending.get(postId) ?? 0);
  }

  pendingTotal() {
    let total = 0;
    for (const n of this.pending.values()) total += n;
    return total;
  }

  /**
   * Write all current deltas in one transaction.
   * Returns true on success; on failure records `lastError` and leaves
   * `pending` untouched (the failed transaction rolled back completely).
   */
  flush() {
    if (this.flushing || this.pending.size === 0) return true;

    // Snapshot the deltas we are about to persist. Increments that arrive
    // later are safe: they land in `pending` after the snapshot is taken.
    const snapshot = new Map(this.pending);

    this.flushing = true;
    try {
      this.db.transaction(() => {
        for (const [postId, delta] of snapshot) {
          this.upsert.run(postId, delta);
        }
      })();
    } catch (err) {
      // Transaction rolled back atomically. Keep memory as-is so the
      // next flush retries exactly these deltas.
      this.lastError = err;
      return false;
    } finally {
      this.flushing = false;
    }

    // Committed -> now (and only now) subtract what we persisted.
    for (const [postId, delta] of snapshot) {
      const remaining = (this.pending.get(postId) ?? 0) - delta;
      if (remaining > 0) this.pending.set(postId, remaining);
      else this.pending.delete(postId);
    }
    this.lastError = null;
    this.flushCount += 1;
    return true;
  }
}

