import test from 'node:test';
import assert from 'node:assert/strict';
import Database from 'better-sqlite3';
import { ViewStore } from '../src/views.js';
import { createApp } from '../src/app.js';

const IDS = ['a', 'b', 'c'];

async function withServer(store, fn) {
  const server = createApp(store).listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  try {
    return await fn(base);
  } finally {
    await new Promise((resolve) => server.close(resolve));
    store.stop();
  }
}

const get = async (url) => (await fetch(url)).json();

async function viewsForAll(base) {
  const out = {};
  for (const id of IDS) out[id] = (await get(`${base}/posts/${id}/views`)).views;
  return out;
}

test('hammer: 300 concurrent increments across 3 ids are exact at every observation point', async () => {
  const db = new Database(':memory:');
  const store = new ViewStore({ db, intervalMs: 500, threshold: 100 });
  store.start();

  await withServer(store, async (base) => {
    // Sample reads concurrently while the hammer is in flight.
    const samples = [];
    const sampler = setInterval(async () => {
      samples.push(await viewsForAll(base));
    }, 5);

    // 300 concurrent GET /posts/:id requests, 100 per id.
    const requests = [];
    for (let i = 0; i < 300; i++) {
      requests.push(get(`${base}/posts/${IDS[i % 3]}`));
    }
    await Promise.all(requests);
    clearInterval(sampler);
    await new Promise((r) => setTimeout(r, 30)); // let last sample land

    // Observation point 1: every concurrent read was exact and consistent.
    for (const sample of samples) {
      const total = IDS.reduce((s, id) => s + sample[id], 0);
      assert.ok(total >= 0 && total <= 300, `total in [0,300], got ${total}`);
      assert.ok(
        Number.isInteger(total),
        'reads must never see partial/torn state'
      );
    }
    for (let i = 1; i < samples.length; i++) {
      const prev = samples[i - 1];
      const cur = samples[i];
      for (const id of IDS) {
        assert.ok(
          cur[id] >= prev[id],
          `views(${id}) must be monotonically non-decreasing`
        );
      }
    }

    // Observation point 2: immediately after all responses, reads are exact.
    const afterHammer = await viewsForAll(base);
    assert.equal(
      IDS.reduce((s, id) => s + afterHammer[id], 0),
      300,
      'DB rows + pending memory must equal 300 right after hammering'
    );

    // Force a flush.
    assert.equal(store.flush(), true);

    // Observation point 3: after flush, DB alone holds all 300.
    const afterFlush = await viewsForAll(base);
    assert.equal(store.pendingTotal(), 0, 'memory zeroed after commit');
    assert.deepEqual(afterFlush, { a: 100, b: 100, c: 100 });

    const rows = db.prepare('SELECT post_id, views FROM post_views').all();
    assert.equal(
      rows.reduce((s, r) => s + r.views, 0),
      300,
      'DB rows alone equal 300 after flush'
    );
    assert.deepEqual(
      Object.fromEntries(rows.map((r) => [r.post_id, r.views])),
      { a: 100, b: 100, c: 100 }
    );
  });
});

test('threshold: any counter exceeding 100 triggers an immediate flush', async () => {
  const db = new Database(':memory:');
  const store = new ViewStore({ db, intervalMs: 60_000, threshold: 100 }); // loop effectively off

  for (let i = 0; i < 101; i++) store.increment('hot');
  store.increment('cold'); // below threshold, must stay pending

  await new Promise((r) => setTimeout(r, 20)); // let setImmediate flush run
  assert.equal((db.prepare('SELECT views FROM post_views WHERE post_id = ?').get('hot') ?? { views: 0 }).views, 101);
  assert.equal(store.views('cold'), 1);
  assert.equal((store.select.get('cold')?.views ?? 0), 0, 'cold stays in memory');
  store.stop();
});

test('flush failure: mocked statement throws once -> retry loses nothing, double-counts nothing', async () => {
  const db = new Database(':memory:');
  const store = new ViewStore({ db, intervalMs: 500, threshold: 100 });
  store.start();

  const real = store.upsert;
  let calls = 0;
  store.upsert = {
    run(...args) {
